Here is the commit message:
powerpc/smp: Add check for kcalloc() failure in
 parse_thread_groups()

As kcalloc() may fail, check its return value to avoid a NULL pointer
dereference when passing it to of_property_read_u32_array().

Fixes: 790a1662d3a26 ("powerpc/smp: Parse ibm,thread-groups with multiple properties")
Cc: stable@vger.kernel.org
Reviewed-by: Christophe Leroy <christophe.leroy@csgroup.eu>
Signed-off-by: Guangshuo Li <lgs201920130244@gmail.com>
Signed-off-by: Madhavan Srinivasan <maddy@linux.ibm.com>
Link: https://patch.msgid.link/20250923133235.1862108-1-lgs201920130244@gmail.com

Here is the root cause:
The function parse_thread_groups() calls kcalloc() to allocate memory for thread_group_array, but does not check if the allocation fails. If kcalloc() returns NULL, the subsequent call to of_property_read_u32_array() passes this NULL pointer, causing a NULL pointer dereference.

Here is the patch:
  */
 static int parse_thread_groups(struct device_node *dn,
 			       struct thread_groups_list *tglp)
 {
 	unsigned int property_idx = 0;
 	u32 *thread_group_array;
 	size_t total_threads;
 	int ret = 0, count;
 	u32 *thread_list;
 	int i = 0;

 	count = of_property_count_u32_elems(dn, "ibm,thread-groups");
 	thread_group_array = kcalloc(count, sizeof(u32), GFP_KERNEL);
+	if (!thread_group_array)
+		return -ENOMEM;
 	ret = of_property_read_u32_array(dn, "ibm,thread-groups",
 					 thread_group_array, count);
 	if (ret)
 		goto out_free;

 	while (i < count && property_idx < MAX_THREAD_GROUP_PROPERTIES) {
 		int j;
 		struct thread_groups *tg = &tglp->property_tgs[property_idx++];

 		tg->property = thread_group_array[i];
 		tg->nr_groups = thread_group_array[i + 1];
 		tg->threads_per_group = thread_group_array[i + 2];
 		total_threads = tg->nr_groups * tg->threads_per_group;

 		thread_list = &thread_group_array[i + 3];

 		for (j = 0; j < total_threads; j++)
 			tg->thread_list[j] = thread_list[j];
 		i = i + 3 + total_threads;
 	}

 	tglp->nr_properties = property_idx;

 out_free:
 	kfree(thread_group_array);
 	return ret;
 }



